10:   const mid = clean.substring(3, 5);
11:   const midNum = Number(mid);
12:   if ((midNum >= 1 && midNum <= 79) || (midNum >= 90 && midNum <= 99)) return '개인사업자';
13:   if (['81', '86', '87', '88'].includes(mid)) return '영리법인본점';
