20: function isValidCorpNo(corpNo) {
21:   if (!corpNo) return false;
22:   const clean = corpNo.replace(/[^0-9]/g, '');
23:   if (clean.length !== 13) return false;
24:   const weights = [1, 2, 1, 2, 1, 2, 1, 2, 1, 2, 1, 2];
25:   let sum = 0;
26:   for (let i = 0; i < 12; i++) {
27:     sum += Number(clean[i]) * weights[i];
28:   }
29:   const remainder = sum % 10;
30:   const checkDigit = (10 - remainder) % 10;
31:   return Number(clean[12]) === checkDigit;
32: }
